  `card_image_title` varchar(100) NOT NULL,
  `card_image_alt` varchar(100) NOT NULL,
  `card_title` varchar(100) NOT NULL,
  `card_area` text NOT NULL,
  `card_tag` text NOT NULL,
  `card_contact` varchar(100) NOT NULL,
  `card_phone_main` varchar(100) NOT NULL,
  `card_phone_spare` varchar(100) NOT NULL,
  `card_line_id` varchar(100) NOT NULL,
  `card_content` text,
  `card_remark` text,
  `card_refresh` int(11) NOT NULL DEFAULT '0',
  `card_area_quota` int(10) NOT NULL DEFAULT '0',
  `card_listing` datetime DEFAULT NULL,
  `card_delisting` datetime DEFAULT NULL,
  `card_sticky_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `card_expiry_time` datetime NOT NULL,
  `card_create_time` datetime NOT NULL,
  `card_update_time` datetime DEFAULT NULL,
  `card_delete_time` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

